SELECT /*selectSellerMpRqQuotaProceState*/ Z.NUM, Z.QUOTATION_NO, Z.QUOTATION_SEQ, Z.AGENT_SOURCING_STATUS, Z.ATOS_DATE, SUBSTR(Z.ATOS_DATE,1,4) || '/' || SUBSTR(Z.ATOS_DATE,5,2) || '/' || SUBSTR(Z.ATOS_DATE,7,2) AS ATOS_DATE2, Z.DESCRIPTION, Z.UNIT_MEASURE, Z.MAKER_NAME, Z.BUYER_TARGET_PRICE, Z.LEAD_TIME, Z.BTOA_USER_NAME, Z.AGENT_REVISION, Z.BUYER_ITEM_NO, Z.BTOA_END_DATE, Z.SPECIFICATION, Z.ITEM_QTY, Z.ORIGIN_NAME, Z.STOA_LIST_PRICE, Z.STOA_VAT_LIST_PRICE, Z.STOA_LIST_AMT, Z.BTOA_USER_DEPT, Z.BUYER, Z.REVISION, Z.AGENT, Z.BTOA_END_TIME, Z.STOA_REMARK, DECODE(Z.STOA_REMARK,'','',SUBSTR(Z.STOA_REMARK,0,5) || '...') AS STOA_REMARK_M, Z.ATOB_REMARK, Z.AGENT_REVISION1, Z.KEP_USER_ID, SUBSTR(Z.ATOS_END_DATE,1,4) || '/' || SUBSTR(Z.ATOS_END_DATE,5,2) || '/' || SUBSTR(Z.ATOS_END_DATE,7,2) || ' ' || SUBSTR(Z.ATOS_END_TIME,0,2) || ':' || SUBSTR(Z.ATOS_END_TIME,3,2) AS ATOS_END_DATE, Z.REMARK_URL, Z.SEL_USER_ID, Z.SELLER_IMAGE_KEY, Z.CMS_CATEG_ID, Z.CMS_CATLG_ID, Z.CMS_SPEC, Z.REF_NO, Z.MIN_ORDER_QTY, Z.PUR_UNIT_QTY, Z.SELLER_AREA, Z.PROCESS_TYPE, Z.PROCESS_NM, Z.RFQ_IMG_FLAG, Z.IMGFILE_DIR, Z.IMGFILE_NAME, Z.TAX_TYPE, Z.ITEM_MAKE_TYPE, Z.MODIFY_FLAG, Z.PRE_GR_FLAG, Z.TAX_TYPE_CD FROM ( SELECT ROWNUM NUM, Y.QUOTATION_NO, Y.QUOTATION_SEQ, Y.AGENT_SOURCING_STATUS, Y.ATOS_DATE, Y.DESCRIPTION, Y.UNIT_MEASURE, Y.MAKER_NAME, Y.BUYER_TARGET_PRICE, Y.LEAD_TIME, Y.BTOA_USER_NAME, Y.AGENT_REVISION, Y.BUYER_ITEM_NO, Y.BTOA_END_DATE, Y.SPECIFICATION, Y.ITEM_QTY, Y.ORIGIN_NAME, Y.STOA_LIST_PRICE, Y.STOA_VAT_LIST_PRICE, Y.STOA_LIST_AMT, Y.BTOA_USER_DEPT, Y.BUYER, Y.REVISION, Y.AGENT, Y.BTOA_END_TIME, Y.STOA_REMARK, Y.ATOB_REMARK, Y.AGENT_REVISION1, Y.KEP_USER_ID, Y.ATOS_END_DATE, Y.ATOS_END_TIME, Y.REMARK_URL, Y.SEL_USER_ID, Y.SELLER_IMAGE_KEY, Y.CMS_CATEG_ID, Y.CMS_CATLG_ID, Y.CMS_SPEC, Y.REF_NO, Y.MIN_ORDER_QTY, Y.PUR_UNIT_QTY, Y.SELLER_AREA, Y.PROCESS_TYPE, Y.PROCESS_NM, Y.RFQ_IMG_FLAG, Y.IMGFILE_DIR, Y.IMGFILE_NAME, Y.TAX_TYPE, Y.ITEM_MAKE_TYPE, Y.MODIFY_FLAG, Y.PRE_GR_FLAG, Y.TAX_TYPE_CD FROM ( SELECT X.QUOTATION_NO, X.QUOTATION_SEQ, X.AGENT_SOURCING_STATUS, X.ATOS_DATE, X.DESCRIPTION, X.UNIT_MEASURE, X.MAKER_NAME, X.BUYER_TARGET_PRICE, X.LEAD_TIME, X.BTOA_USER_NAME, X.AGENT_REVISION, X.BUYER_ITEM_NO, X.BTOA_END_DATE, X.SPECIFICATION, X.ITEM_QTY, X.ORIGIN_NAME, X.STOA_LIST_PRICE, X.STOA_VAT_LIST_PRICE, X.STOA_LIST_AMT, X.BTOA_USER_DEPT, X.BUYER, X.REVISION, X.AGENT, X.BTOA_END_TIME, X.STOA_REMARK, X.ATOB_REMARK, X.AGENT_REVISION1, X.KEP_USER_ID, X.ATOS_END_DATE, X.ATOS_END_TIME, X.REMARK_URL, X.SEL_USER_ID, X.SELLER_IMAGE_KEY, X.CMS_CATEG_ID, X.CMS_CATLG_ID, X.CMS_SPEC, X.REF_NO, X.MIN_ORDER_QTY, X.PUR_UNIT_QTY, X.SELLER_AREA, X.PROCESS_TYPE, X.PROCESS_NM, X.RFQ_IMG_FLAG, X.IMGFILE_DIR, X.IMGFILE_NAME, X.TAX_TYPE, X.ITEM_MAKE_TYPE, X.MODIFY_FLAG, X.PRE_GR_FLAG, X.TAX_TYPE_CD FROM ( SELECT A.QUOTATION_NO, A.QUOTATION_SEQ, /* 고객사의 차수가 증가할 경우 협력사는 진행단계에 관계없이 무조건 차수증가 종료가됨*/ CASE WHEN B.RECV_FLAG ='GD' THEN '견적취소' ELSE CASE WHEN A.STATUS='O' AND B.STATUS='O' THEN '차수증가종료' ELSE CASE WHEN NVL(A.STOA_LIST_PRICE, 0)=0 AND A.ATOS_END_DATE||A.ATOS_END_TIME < TO_CHAR(SYSDATE, 'YYYYMMDDHH24MMSS') THEN '견적미제출' ELSE CASE WHEN NVL(A.STOA_LIST_PRICE, 0)=0 AND (SELECT COUNT(*) FROM KEPQTDT QT WHERE QT.BUYER=A.BUYER AND QT.QUOTATION_NO=A.QUOTATION_NO AND QT.QUOTATION_SEQ=A.QUOTATION_SEQ AND QT.REVISION=A.REVISION AND QT.STATUS <> 'D' AND QT.AGENT=A.AGENT)=1 AND A.ATOS_END_DATE||A.ATOS_END_TIME >= TO_CHAR(SYSDATE, 'YYYYMMDDHH24MMSS') THEN '신규견적요청' ELSE CASE WHEN NVL(A.STOA_LIST_PRICE, 0)=0 THEN '재견적요청' ELSE CASE WHEN A.STOA_LIST_PRICE<>0 AND B.RECV_FLAG IN ('GA', 'GS','GR', 'PM') THEN '견적제출' ELSE CASE WHEN A.BID_SUCCESS_FLAG='Y' THEN '단가선정' ELSE CASE WHEN A.BID_SUCCESS_FLAG='N' THEN '단가미선정' END END END END END END END END AS AGENT_SOURCING_STATUS, A.ATOS_DATE, A.DESCRIPTION, A.UNIT_MEASURE, A.MAKER_NAME, B.BUYER_TARGET_PRICE, A.LEAD_TIME, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = B.KEP_USER_ID) AS BTOA_USER_NAME, (SELECT COUNT(*) FROM KEPQTDT QT WHERE QT.BUYER=A.BUYER AND QT.QUOTATION_NO=A.QUOTATION_NO AND QT.QUOTATION_SEQ=A.QUOTATION_SEQ AND QT.REVISION=A.REVISION AND QT.STATUS <> 'D' AND QT.AGENT=A.AGENT) AS AGENT_REVISION1, A.BUYER_ITEM_NO, B.BTOA_END_DATE, SUBSTR(NVL(TRIM(B.BTOA_END_TIME),'19'),0,2) AS BTOA_END_TIME, A.SPECIFICATION, A.ITEM_QTY, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE='M001' AND CODE=A.ORIGIN_NAME) AS ORIGIN_NAME, DECODE(A.TAX_TYPE,'12',A.STOA_LIST_PRICE,DECODE(A.VAT_YN,'Y',ROUND(A.STOA_LIST_PRICE/1.1), A.STOA_LIST_PRICE)) AS STOA_LIST_PRICE, DECODE(A.TAX_TYPE,'12',A.STOA_LIST_PRICE,DECODE(A.VAT_YN,'Y',A.STOA_LIST_PRICE, ROUND(A.STOA_LIST_PRICE*1.1))) AS STOA_VAT_LIST_PRICE, (A.ITEM_QTY * A.STOA_LIST_PRICE) AS STOA_LIST_AMT, (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE=B.BUYER AND TYPE='C001' AND CODE=B.BTOA_USER_DEPT) AS BTOA_USER_DEPT, A.BUYER, A.REVISION, A.AGENT, NVL(TRIM(A.STOA_REMARK),'') AS STOA_REMARK, NVL(TRIM(B.ATOB_REMARK),'') AS ATOB_REMARK, TRIM(A.AGENT_REVISION) AS AGENT_REVISION, TRIM(B.KEP_USER_ID) AS KEP_USER_ID, TRIM(A.ATOS_END_DATE) AS ATOS_END_DATE, TRIM(A.ATOS_END_TIME) AS ATOS_END_TIME, TRIM(B.REMARK_URL) AS REMARK_URL, TRIM(A.SEL_USER_ID) AS SEL_USER_ID, TRIM(A.SELLER_IMAGE_KEY) AS SELLER_IMAGE_KEY, B.CMS_CATEG_ID, B.CMS_CATLG_ID, (SELECT SPECIFICATION FROM CMSCATLG WHERE CMS_CATLG_ID = B.CMS_CATLG_ID) AS CMS_SPEC, B.REF_NO, A.MIN_ORDER_QTY, A.PUR_UNIT_QTY, A.SELLER_AREA, A.PROCESS_TYPE, (SELECT TEXT2 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M034' AND COD.FLAG = 'Y' AND COD.CODE = A.PROCESS_TYPE) AS PROCESS_NM, NVL(B.RFQ_IMG_FLAG,'N') AS RFQ_IMG_FLAG, A.IMGFILE_DIR, A.IMGFILE_NAME, (SELECT TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE='TX17' AND COD.CODE = A.TAX_TYPE) AS TAX_TYPE, A.TAX_TYPE AS TAX_TYPE_CD, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M132' AND CODE = A.ITEM_MAKE_TYPE) AS ITEM_MAKE_TYPE, CASE WHEN NVL(A.STOA_LIST_PRICE, 0) > 0 THEN CASE WHEN A.ATOS_END_DATE||A.ATOS_END_TIME > TO_CHAR(SYSDATE, 'YYYYMMDDHH24MMSS') THEN CASE WHEN A.ADMIN_CLOSE_FLAG = 'N' THEN CASE WHEN B.ATOB_SEND_FLAG = 'N' THEN CASE WHEN (SELECT COUNT(*) FROM KEPQTDT WHERE 1=1 AND BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND AGENT_REVISION = A.AGENT_REVISION AND STATUS = 'C' AND BID_SUCCESS_FLAG = 'Y') = 0 THEN 'Y' ELSE 'N' END ELSE 'N' END ELSE 'N' END ELSE 'N' END ELSE 'N' END AS MODIFY_FLAG, A.PRE_GR_FLAG FROM KEPQTDT A, KEPRQDT B WHERE A.AGENT = #{st_com_code} AND A.BUYER=B.BUYER AND A.QUOTATION_NO=B.QUOTATION_NO AND A.QUOTATION_SEQ=B.QUOTATION_SEQ AND A.REVISION=B.REVISION AND B.SO_CA_FLAG='SO' AND TO_CHAR(A.ATOS_DATE) BETWEEN #{st_from_date} AND #{st_to_date}
AND A.QUOTATION_NO LIKE '%'||#{st_quotation_no}||'%'
AND A.DESCRIPTION LIKE '%'||#{st_description}||'%'
AND A.SPECIFICATION LIKE '%'||#{st_specification}||'%'
/* 고객사의 차수가 증가할 경우 협력사는 진행단계에 관계없이 무조건 차수증가 종료가됨 */ AND CASE WHEN B.RECV_FLAG ='GD' THEN '견적취소' ELSE CASE WHEN A.STATUS='O' AND B.STATUS='O' THEN '차수증가종료' ELSE CASE WHEN NVL(A.STOA_LIST_PRICE, 0)=0 AND A.ATOS_END_DATE||A.ATOS_END_TIME < TO_CHAR(SYSDATE, 'YYYYMMDDHH24MMSS') THEN '견적미제출' ELSE CASE WHEN NVL(A.STOA_LIST_PRICE, 0)=0 AND (SELECT COUNT(*) FROM KEPQTDT QT WHERE QT.BUYER=A.BUYER AND QT.QUOTATION_NO=A.QUOTATION_NO AND QT.QUOTATION_SEQ=A.QUOTATION_SEQ AND QT.REVISION=A.REVISION AND QT.STATUS <> 'D' AND QT.AGENT=A.AGENT)=1 AND A.ATOS_END_DATE||A.ATOS_END_TIME >= TO_CHAR(SYSDATE, 'YYYYMMDDHH24MMSS') THEN '신규견적요청' ELSE CASE WHEN NVL(A.STOA_LIST_PRICE, 0)=0 THEN '재견적요청' ELSE CASE WHEN A.STOA_LIST_PRICE<>0 AND B.RECV_FLAG IN ('GA', 'GS','GR','PM') THEN '견적제출' ELSE CASE WHEN A.BID_SUCCESS_FLAG='Y' AND B.RECV_FLAG='CM' THEN '단가선정' ELSE CASE WHEN A.BID_SUCCESS_FLAG='N' AND B.RECV_FLAG='CM' THEN '단가미선정' END END END END END END END END LIKE '%'||#{st_sourcing_status}||'%'
AND A.STATUS IN ('C','R','O') AND B.STATUS IN ('C','R','O') ORDER BY A.QUOTATION_NO, A.QUOTATION_SEQ, A.AGENT_REVISION ) X ) Y ) Z

mapper.update:

/*updateSellerMpRqQuotaProceState*/
UPDATE	KEPQTDT A
SET		STOA_LIST_PRICE = DECODE(A.TAX_TYPE, '12', #{stoa_list_price}, DECODE(A.VAT_YN, 'Y', ROUND(#{stoa_list_price}*1.1), #{stoa_list_price}))
		, LEAD_TIME = #{lead_time}    
WHERE	1=1
AND		BUYER = #{buyer}
AND		QUOTATION_NO = #{quotation_no}
AND		QUOTATION_SEQ = #{quotation_seq}
AND		REVISION = #{revision}
AND		AGENT = #{agent}
AND		AGENT_REVISION = #{agent_revision}
